def icon(name, cls='h-4 w-4'):
    """Return an inline Lucide SVG. Unknown names render nothing (never a broken glyph)."""
    paths = _P.get(name)
    if not paths:
        return Markup('')
    return Markup(
        f'<svg class="icon {cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">{paths}</svg>'
    )
